-- ============================================================
-- SEED EXT 6: Módulo 12 — Conditional 2 & 3 (ex 202-300)
-- Tópicos: Type 2 (unreal present/future), Type 3 (unreal past),
-- mixed conditionals, unless/provided/as long as, TOEFL integrado
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'conditional-2-3';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo conditional-2-3 não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 71: Type 2 — situações hipotéticas formais
  (cid,71,202,'gap_fill','If _____ (the) _____ (institution) _____ (have) _____ (a) _____ stronger _____ (mandate), it _____ (be/able) to _____ (enforce) _____ (compliance) more _____ effectively — but without _____ (the) _____ political _____ (will) of _____ (its) _____ (member) _____ (states), _____ (even) _____ such _____ (a) _____ mandate _____ (prove/would) hollow.','the / institutions / had / a / stronger / mandate / would be able / to / enforce / compliance / more / effectively / but / without / the / political / will / its / member / states / even / such / a / mandate / would prove / hollow',NULL,'Type 2: ''If institutions had stronger mandate, would be able to enforce'' for institutional design analysis.','hard'),
  (cid,71,203,'gap_fill','Were _____ (the) _____ evidence _____ (unambiguous), _____ (the) _____ (case) for _____ action _____ (be/would) _____ overwhelming — _____ but _____ (it) _____ _____ (rarely/is), and _____ (those) _____ who _____ _____ (seek) to _____ (delay) action _____ (exploit/would) _____ (the) _____ ambiguity _____ _____ (effectively/most) if _____ no _____ (precautionary) _____ principle _____ (apply/were/to).','Were / the / evidence / unambiguous / the / case / for / action / would be / overwhelming / but / it / is rarely so / those / who / seek / delay / action / would exploit / the / ambiguity / most effectively / if / no / precautionary / principle / were to apply',NULL,'Inverted Type 2: ''Were the evidence unambiguous, would be overwhelming'' + nested conditional.','hard'),
  (cid,71,204,'gap_fill','If _____ (the) _____ (organization) _____ (operate) _____ under _____ (a) _____ different _____ (set) of _____ incentives, _____ (it) _____ _____ (might/prioritize) _____ long-term _____ (sustainability) over _____ short-term _____ gains — but _____ (the) _____ incentive _____ (structure) _____ (itself/be) _____ (a) _____ product of _____ (the) _____ political _____ arrangements _____ (which/within) _____ (it) _____ (function).','the / organization / operated / under / a / different / set / incentives / it / might prioritize / long-term / sustainability / over / short-term / gains / the / incentive / structure / is itself / a / product / the / political / arrangements / within which / it / functions',NULL,'Type 2: ''If operated under different incentives, might prioritize'' for institutional incentive analysis.','hard'),
  (cid,71,205,'gap_fill','If _____ (policymaker) _____ (be/able) to _____ (act) on _____ (the) _____ (best/available) _____ evidence _____ (rather/than) responding to _____ (the/most/immediate) _____ political _____ (pressure), _____ (the) _____ (quality) of _____ (policy) _____ (improve/would) dramatically — _____ (a) _____ counterfactual _____ (that) _____ (reveal) _____ (how/much) _____ (we/lose) by _____ (the/absence) of _____ (insulated) _____ deliberative _____ (space).','policymakers / were able / to / act / on / the / best available / evidence / rather than / responding / the most immediate / political / pressure / the / quality / policy / would improve / dramatically / a / counterfactual / that / reveals / how much / we lose / the absence / insulated / deliberative / space',NULL,'Type 2: ''If policymakers were able to act, would improve'' for evidence-based policy argument.','hard'),
  (cid,71,206,'gap_fill','Should _____ (the) _____ (reform) _____ (implement/passive) _____ as _____ (design/passive), _____ (it) _____ _____ (likely/would/address) _____ (the) _____ most _____ (pressing) _____ (concern) _____ raised _____ by _____ (the) _____ (commission) — but _____ (few) _____ _____ (who/observe) _____ (the) _____ political _____ landscape _____ _____ (expect) _____ full _____ implementation.','Should / the / reform / be implemented / as / designed / it / would likely address / the / most / pressing / concerns / raised / by / the / commission / few / who observe / the / political / landscape / expect / full / implementation',NULL,'Inverted Type 2 ''Should the reform be implemented'': hypothetical policy analysis.','hard'),
  (cid,71,207,'gap_fill','If _____ (we) _____ (take) _____ (seriously) _____ (the) _____ claims _____ (make/passive) by _____ (the) _____ model, _____ (we) _____ _____ (ought/to/reach) _____ (conclusion) _____ (quite/different) from _____ (those) _____ (dominate) _____ (the) _____ current _____ debate — but _____ (the) _____ model _____ (itself) _____ (rest) on _____ assumptions _____ (that) _____ (many) _____ (dispute).','If / we / took / seriously / the / claims / made / by / the / model / we / ought to reach / conclusions / quite different / from / those / dominating / the / current / debate / the / model / itself / rests / on / assumptions / that / many / dispute',NULL,'Type 2 ''If we took seriously...ought to reach'' for academic model evaluation.','hard'),
  (cid,71,208,'multiple_choice','Which Type 2 conditional MOST correctly expresses a hypothetical in formal academic writing?','Were the funding made available, the research could proceed immediately.','[''If the funding would be made available, the research could proceed immediately.'',''Were the funding made available, the research could proceed immediately.'',''If the funding is made available, the research could proceed immediately.'',''Had the funding been made available, the research could proceed immediately.'']','Inverted Type 2 ''Were the funding made available'' = most formal. Option C = Type 1 (real). Option D = Type 3 (past).','medium'),
  (cid,71,209,'gap_fill','If _____ (the) _____ (state) _____ (invest) _____ adequately in _____ (public) _____ (education), _____ (the) _____ returns _____ in _____ terms of _____ (economic) _____ productivity and _____ (social) _____ (cohesion) _____ (far/exceed) _____ (the) _____ initial _____ (outlay) — _____ (a) _____ case _____ (that) _____ (command/would) _____ (broader) _____ support _____ (if) _____ (evidence/the) _____ (present/passive) more _____ effectively.','the / state / invested / adequately / public / education / the / returns / in / terms / economic / productivity / social / cohesion / would far exceed / the / initial / outlay / a / case / that / would command / broader / support / if / the evidence / were presented / more / effectively',NULL,'Type 2 ''If invested/would exceed'' + nested ''if were presented/would command'' for education policy argument.','hard'),

  -- BLOCK 72: Type 3 — consequências de decisões passadas
  (cid,72,210,'gap_fill','Had _____ (the) _____ (decision-maker) _____ (heed) _____ (the) _____ early _____ (warning) _____ (signal), _____ (the) _____ subsequent _____ (crisis) _____ (avert/might/passive) — _____ (but) _____ (the) _____ institutional _____ (design) _____ _____ (discourage) early _____ action _____ by _____ (reward) _____ (those/who) _____ (wait) for _____ certainty.','Had / the / decision-makers / heeded / the / early / warning / signals / the / subsequent / crisis / might have been averted / but / the / institutional / design / discouraged / early / action / by / rewarding / those who / waited / for / certainty',NULL,'Type 3: ''Had heeded, might have been averted'' for institutional failure analysis with counterfactual.','hard'),
  (cid,72,211,'gap_fill','If _____ (the) _____ (coalition) _____ (maintain) _____ its _____ (unity) _____ through _____ (the) _____ transition, _____ (the) _____ (reform) _____ (consolidate/would/have) much _____ more _____ (rapidly) — _____ (instead), _____ (the) _____ (fracture) that _____ (develop/occurred) in _____ its _____ _____ (second/year) _____ (leave) _____ (the) _____ reform _____ _____ (unfinished) and _____ vulnerable.','If / the / coalition / had maintained / its / unity / through / the / transition / the / reforms / would have consolidated / much / more / rapidly / instead / the / fracture / that occurred / in / its / second year / left / the / reform / unfinished / vulnerable',NULL,'Type 3 ''If had maintained, would have consolidated'' for coalition dynamics analysis.','hard'),
  (cid,72,212,'gap_fill','Had _____ (the) _____ (researcher) _____ (adopt) _____ (a) _____ more _____ (robust) _____ (design), _____ (the) _____ (finding) _____ _____ (not/have/would/attract) _____ (the) _____ (criticism) _____ they _____ _____ (subsequently/encounter) — _____ (the) _____ methodological _____ (shortcuts) _____ (take/passive) _____ in _____ (the) _____ interest of _____ speed _____ (ultimately/prove) _____ (more/costly) than _____ (the) _____ (time) they _____ (save).','Had / the / researchers / adopted / a / more / robust / design / the / findings / would not have attracted / the / criticism / they / subsequently encountered / the / methodological / shortcuts / taken / in / the / interest / speed / ultimately proved / more costly / than / the / time / they / saved',NULL,'Type 3 ''Had adopted, would not have attracted'' for research methodology hindsight analysis.','hard'),
  (cid,72,213,'gap_fill','If _____ (the) _____ (government) _____ (respond) _____ earlier to _____ (the) _____ (emerging) _____ (threat), _____ (the) _____ (economic) _____ (cost) of _____ (the) _____ eventual _____ (response) _____ _____ (substantially/less/be/would/have) — _____ (the) _____ delay _____ (prove) _____ both _____ (costly) in _____ (its) _____ own _____ right and _____ (limiting) of _____ (the) _____ (option) that _____ _____ (remain/available/remained).','If / the / government / had responded / earlier / the / emerging / threat / the / economic / costs / the / eventual / response / would have been substantially less / the / delay / proved / both / costly / its / own / right / limiting / the / options / that / remained available',NULL,'Type 3 ''If had responded, would have been less'' for government response timing analysis.','hard'),
  (cid,72,214,'gap_fill','Had _____ (policymaker) _____ (take) _____ (the) _____ (distributional) _____ (consequence) _____ of _____ (the) _____ reform _____ more _____ (seriously), _____ (they) _____ _____ (build/might/have) _____ (the) _____ (compensatory) _____ mechanisms _____ (need/passive) to _____ (maintain) _____ _____ (support) — _____ (instead), _____ (the) _____ (backlash) from _____ those _____ (most) _____ _____ (adversely) _____ (affect/passive) _____ (reverse/ultimately) _____ the _____ reform _____ entirely.','Had / policymakers / taken / the / distributional / consequences / of / the / reform / more / seriously / they / might have built / the / compensatory / mechanisms / needed / maintain / political / support / instead / the / backlash / from / those / most / adversely / affected / ultimately reversed / the / reform / entirely',NULL,'Type 3 ''Had taken seriously, might have built'' for distributive politics hindsight.','hard'),
  (cid,72,215,'multiple_choice','Which Type 3 conditional sentence is grammatically MOST correct?','Had the committee consulted the relevant stakeholders, it would have produced a more widely accepted recommendation.','[''If the committee would have consulted the relevant stakeholders, it would produce a more widely accepted recommendation.'',''Had the committee consulted the relevant stakeholders, it would have produced a more widely accepted recommendation.'',''If the committee consulted the relevant stakeholders, it would produce a more widely accepted recommendation.'',''Had the committee had consulted the relevant stakeholders, it could produce a more widely accepted recommendation.'']','Correct Type 3 inverted: ''Had the committee consulted + would have produced.'' Option A ''would have consulted'' is incorrect in if-clause.','easy'),
  (cid,72,216,'gap_fill','Had _____ (the) _____ (architect) _____ of _____ (the) _____ system _____ (anticipate) _____ (the) _____ scale of _____ (the) _____ adoption, _____ (they) _____ _____ (design/would/have) _____ (the) _____ infrastructure _____ (differently) — _____ but _____ (the/failure) to _____ (plan) for _____ (success) _____ (be) _____ one of _____ (the) _____ most _____ (common) _____ (and/costly) _____ mistakes in _____ (institutional) _____ design.','Had / the / architects / of / the / system / anticipated / the / scale / the / adoption / they / would have designed / the / infrastructure / differently / but / the failure / to / plan / for / success / is / one / the / most / common / and costly / mistakes / institutional / design',NULL,'Type 3 ''Had anticipated, would have designed differently'' for institutional planning failure.','hard'),
  (cid,72,217,'gap_fill','If _____ (the) _____ (treaty) _____ (include) _____ (stronger) _____ (enforcement) _____ (mechanism), _____ (it) _____ _____ (might/prove) _____ more _____ (durable) — _____ (the) _____ (decision) to _____ (prioritize) _____ (breadth) of _____ (membership) over _____ (the) _____ (stringency) of _____ (commitment) _____ (be) _____ (a) _____ _____ (choice/deliberate) whose _____ _____ (consequence) _____ (unfold/passive) only _____ over _____ time.','If / the / treaty / had included / stronger / enforcement / mechanisms / it / might have proved / more / durable / the / decision / to / prioritize / breadth / membership / over / the / stringency / commitment / was / a / deliberate / choice / whose / consequences / only unfolded / over / time',NULL,'Type 3 ''If had included, might have proved'' for treaty design trade-off analysis.','hard'),

  -- BLOCK 73: Mixed conditionals
  (cid,73,218,'gap_fill','If _____ (the) _____ (institution) _____ (not/establish) _____ (the) _____ _____ (procedural) norms _____ it _____ (now) _____ (maintain), _____ (it) _____ _____ (not/able/would/be) to _____ (function) _____ as _____ legitimately _____ as _____ (it) _____ does _____ today — _____ (a) _____ classic _____ mixed _____ (conditional) _____ illustrating how _____ past _____ (investment) _____ (shape) _____ present _____ capacity.','If / the / institution / had not established / the / procedural / norms / it / now / maintains / it / would not be able / to / function / as / legitimately / as / it / does / today / a / classic / mixed / conditional / illustrating / past / investment / shapes / present / capacity',NULL,'Mixed conditional: Type 3 if-clause (past action) + Type 2 result (present state) for institutional norms.','hard'),
  (cid,73,219,'gap_fill','Had _____ (the) _____ reformers _____ (succeed) _____ in _____ (their) _____ initial _____ (effort), _____ (the) _____ (institution) _____ _____ (currently/be/would) _____ operating _____ under _____ (a) _____ quite _____ different _____ (framework) — _____ (the) _____ (failure) of _____ (the) _____ (reform) _____ (explain) much about _____ (the) _____ constraints _____ (within/which) _____ (it) _____ (operate/continues) today.','Had / the / reformers / succeeded / in / their / initial / efforts / the / institution / would currently be / operating / under / a / quite / different / framework / the / failure / of / the / reform / explains / much / the / constraints / within which / it / continues to operate / today',NULL,'Mixed conditional: ''Had succeeded'' (past) + ''would currently be operating'' (present result) for reform failure analysis.','hard'),
  (cid,73,220,'gap_fill','If _____ (the) _____ (original) _____ (design) _____ (include) _____ _____ (adequate) _____ (safeguard), _____ (we) _____ _____ (now/facing/not/would) _____ (the) _____ _____ (current) _____ (dilemma) — but _____ _____ (design) _____ (fix/cannot) _____ retrospectively, _____ and _____ (the) _____ path _____ forward _____ (must) _____ _____ (work/passive) out _____ within _____ (the) _____ constraints _____ (it) _____ (create).','If / the / original / design / had included / adequate / safeguards / we / would not now be facing / the / current / dilemma / design / cannot be fixed / retrospectively / the / path / forward / must / be worked / out / within / the / constraints / it / created',NULL,'Mixed conditional ''If had included, would not now be facing'' for design lock-in analysis.','hard'),
  (cid,73,221,'gap_fill','If _____ (the) _____ (scholar) _____ _____ (not/spend) _____ (a) _____ decade _____ _____ (build) _____ (the) _____ _____ (methodological) _____ (foundation) for _____ (this) _____ _____ (work), _____ (the) _____ findings _____ (now/produce/would) _____ _____ (not/possible/be) — _____ (investment) _____ in _____ _____ (foundational) _____ (work) _____ (rarely/appreciate/passive) _____ until _____ (its) _____ (fruit/now/apparent/are).','If / the / scholar / had not spent / a / decade / building / the / methodological / foundation / for / this / work / the / findings / now produced / would not be possible / investment / in / foundational / work / is rarely appreciated / until / its / fruits / are now apparent',NULL,'Mixed conditional ''If had not spent, findings would not be possible'' for scholarly foundation value.','hard'),
  (cid,73,222,'gap_fill','Were _____ (the) _____ (situation) _____ different, _____ (the) _____ (response) _____ _____ (would/different/be) — but _____ (it) _____ _____ (not) _____ (it) _____ (because/is) _____ (the) _____ (accumulation) of _____ choices _____ _____ (make/passive) _____ in _____ earlier _____ _____ (period) _____ (continue) to _____ (shape) _____ (what) _____ (now) _____ _____ (possible/is).','Were / the / situation / different / the / response / would be different / but / it / is not / it is because / the / accumulation / choices / made / in / earlier / periods / continues / shape / what / is now / possible',NULL,'Mixed: ''Were situation different'' (present hypothetical) explaining past determination of present.','hard'),
  (cid,73,223,'multiple_choice','Which mixed conditional MOST effectively makes an academic argument?','If the researchers had established the protocols from the outset, the field would currently possess a robust comparative dataset.','[''If the researchers established the protocols from the outset, the field would possess a robust comparative dataset.'',''Had the researchers established the protocols at the outset, the field might currently possess a robust comparative dataset.'',''If the researchers had established the protocols from the outset, the field would currently possess a robust comparative dataset.'',''If the researchers were to establish the protocols from the outset, the field would possess a robust comparative dataset.'']','Mixed conditional: Type 3 if-clause ''had established'' (past) + Type 2 result ''would currently possess'' (present state).','medium'),
  (cid,73,224,'gap_fill','If _____ (the) _____ (program) _____ (not/suffer) _____ (these) _____ _____ (early) _____ (setback), _____ (it) _____ _____ (might/be) _____ in _____ (a) _____ much _____ stronger _____ _____ (position) _____ today — _____ (the) _____ (legacy) of _____ (those) _____ _____ (early) _____ (failure) _____ (persist) _____ in _____ (the) _____ (reduced) _____ (ambition) and _____ (caution) _____ (that) _____ (characterize) _____ (its) _____ current _____ approach.','If / the / program / had not suffered / these / early / setbacks / it / might be / in / a / much / stronger / position / today / the / legacy / those / early / failures / persists / in / the / reduced / ambition / caution / that / characterizes / its / current / approach',NULL,'Mixed conditional ''If had not suffered, might be stronger today'' for institutional trauma analysis.','hard'),
  (cid,73,225,'gap_fill','Had _____ (the) _____ (founders) _____ (anticipate) _____ (the) _____ _____ (range) of _____ _____ (challenge) the _____ (institution) _____ _____ (face/would), _____ (they) _____ _____ (might/build) _____ _____ (different) _____ (safeguard) — _____ (as) _____ (it) _____ _____ (is), _____ (it) _____ _____ (must/now/operate) _____ with _____ tools _____ that _____ _____ (design/were) for _____ (a) _____ _____ (simpler) _____ (world).','Had / the / founders / anticipated / the / range / of / challenges / the / institution / would face / they / might have built / different / safeguards / as / it / is / it / must now operate / with / tools / that / were designed / for / a / simpler / world',NULL,'Mixed conditional ''Had anticipated, might have built'' + ''must now operate'' for institutional design limitations.','hard'),

  -- BLOCK 74: Unless, provided that, as long as, only if
  (cid,74,226,'gap_fill','Unless _____ (the) _____ (funding) _____ _____ (substantially/increase), _____ (the) _____ (program) _____ _____ (could/not/expand) to _____ (meet) _____ (the) _____ growing _____ (demand) — _____ (a) _____ constraint _____ _____ (impose/passive) not by _____ (design) but by _____ _____ the _____ budgetary _____ (cycle).','Unless / the / funding / were substantially increased / the / program / could not expand / to / meet / the / growing / demand / a / constraint / imposed / not / design / but / by / the / budgetary / cycle',NULL,'''Unless were substantially increased, could not expand'' = Type 2 hypothetical with unless.','hard'),
  (cid,74,227,'gap_fill','The _____ (agreement) _____ _____ (hold) _____ provided _____ (that) _____ _____ all _____ parties _____ (act) _____ in _____ (good/faith) — but _____ _____ (the/history) of _____ (such) _____ arrangements _____ _____ (suggest/would) that _____ (good/faith) _____ _____ (rarely/assume/passive) _____ (should) without _____ (being) _____ _____ (verify/passive) by _____ independent _____ (mechanism).','agreement / would hold / provided / that / all / parties / acted / in / good faith / the history / such / arrangements / suggests / that / good faith / should rarely be assumed / without / being / verified / independent / mechanisms',NULL,'''Would hold provided that acted'' = ''provided that'' as conditional in agreement analysis.','hard'),
  (cid,74,228,'gap_fill','As _____ long _____ as _____ (the) _____ (incentive) _____ _____ (align), _____ _____ (cooperation) _____ _____ (remain) _____ stable — but _____ (the) _____ (moment) _____ (the/calculus/shifts), _____ (the) _____ (relationship) _____ _____ (fragile/prove) _____ _____ (any/despite) _____ _____ (institutional) _____ (framework) _____ _____ (build/passive) to _____ (support) _____ it.','As / long / as / the / incentives / aligned / cooperation / would remain / stable / the / moment / the calculus shifts / the / relationship / would prove / fragile / despite / any / institutional / framework / built / to / support / it',NULL,'''As long as aligned, would remain'' + ''would prove fragile'' for cooperation stability analysis.','hard'),
  (cid,74,229,'gap_fill','The _____ (reform) _____ _____ (succeed/would) _____ only _____ if _____ (the) _____ _____ (key) _____ _____ (stakeholder) _____ (not/only/support) _____ it _____ publicly _____ but _____ also _____ _____ (use) _____ (their) _____ _____ (influence) _____ to _____ (overcome) _____ (the) _____ _____ (resistance) that _____ would _____ _____ (inevitably) _____ (arise) from _____ those _____ _____ (benefit/most) _____ from _____ _____ (the) _____ status _____ quo.','The / reform / would succeed / only / if / the / key / stakeholders / not only supported / it / publicly / but / also / used / their / influence / to / overcome / the / resistance / that / would inevitably / arise / from / those / benefiting most / from / the / status / quo',NULL,'''Would succeed only if...not only supported but also used'' for reform conditions analysis.','hard'),
  (cid,74,230,'gap_fill','Unless _____ (the) _____ _____ (institution) _____ (willing/be) to _____ (accept) _____ _____ (the) _____ short-term _____ _____ (cost) of _____ _____ (transparency), _____ _____ it _____ _____ (not/be/would/able) to _____ _____ (generate) _____ (the) _____ long-term _____ _____ (trust) _____ on which _____ its _____ _____ (legitimacy) _____ ultimately _____ (depend).','Unless / the / institution / is willing / to / accept / the / short-term / costs / of / transparency / it / would not be able / to / generate / the / long-term / trust / on which / its / legitimacy / ultimately / depends',NULL,'''Unless willing to accept, would not be able to generate'' for institutional transparency argument.','hard'),
  (cid,74,231,'multiple_choice','Which sentence MOST correctly uses ''provided that'' as a conditional in academic writing?','The policy would be effective, provided that all implementing agencies received adequate training and resources.','[''The policy would be effective, provided all implementing agencies received adequate training and resources.'',''The policy would be effective, provided that all implementing agencies received adequate training and resources.'',''The policy would be effective, providing all implementing agencies received adequate training and resources.'',''The policy would be effective, provided that all implementing agencies will receive adequate training and resources.'']','Both A and B are grammatically acceptable; B is most formal. Option C ''providing'' is colloquial. Option D ''will receive'' is inconsistent tense.','medium'),
  (cid,74,232,'gap_fill','Only _____ if _____ (the) _____ (actor) _____ _____ (perceive) _____ that _____ _____ (compliance) _____ is _____ in _____ _____ their _____ _____ (interest) _____ _____ (they/comply) — _____ (an) _____ insight _____ _____ (suggest/that) _____ _____ (the) _____ _____ (enforcement) _____ of _____ _____ international _____ (norm) _____ _____ (rely/should) _____ on _____ _____ _____ (incentive-compatible) _____ design _____ rather than _____ _____ (external) _____ sanction _____ alone.','Only / if / the / actors / perceive / that / compliance / is in / their / interest / will they comply / an / insight / that suggests / the / enforcement / international / norms / should rely / incentive-compatible / design / rather / external / sanctions / alone',NULL,'''Only if perceive, will they comply'' (inversion with only if) for norm compliance analysis.','hard'),
  (cid,74,233,'gap_fill','The _____ _____ (result) _____ _____ (could) _____ _____ (replicate/passive) _____ as _____ long _____ as _____ the _____ _____ (original) _____ _____ (protocol) _____ _____ (follow/passive) _____ exactly — _____ but _____ _____ (the/failure) of _____ _____ (many) _____ _____ (replication) _____ _____ (attempt) _____ _____ (suggest/have) _____ that _____ _____ (the/protocol) _____ _____ (document/passive) _____ _____ (with/sufficient/precision/not/was).','The / results / could / be replicated / as / long / as / the / original / protocol / was followed / exactly / the failure / many / replication / attempts / has suggested / that / the protocol / was not documented / with sufficient precision',NULL,'''Could be replicated as long as protocol was followed'' for replication failure analysis.','hard'),

  -- BLOCK 75: TOEFL Reading com condicionais tipos 2 e 3
  (cid,75,234,'multiple_choice','[TOEFL Reading] ''If the committee had acted on the initial warnings, the subsequent crisis might have been averted.'' This sentence implies that:','The committee did not act on the warnings, and the crisis occurred.','[''The committee acted on the warnings but the crisis occurred anyway.'',''The committee did not act on the warnings, and the crisis occurred.'',''It is uncertain whether the committee acted on the warnings.'',''The committee will act on future warnings to avert crises.'']','Type 3 conditional = unreal past: ''if had acted'' implies they did NOT act, and ''might have been averted'' implies the crisis DID occur.','easy'),
  (cid,75,235,'gap_fill','[TOEFL Reading] ''Were the assumptions underlying this model to hold in practice, the predictions it generates _____ (prove) _____ remarkably accurate.'' The correct verb form is:','would prove',NULL,'Inverted Type 2 conditional: ''Were...to hold'' + ''would prove'' (hypothetical present/future).','medium'),
  (cid,75,236,'multiple_choice','[TOEFL Reading] ''Had the government adopted a more comprehensive approach, the outcomes would have been substantially better.'' The academic purpose of this conditional is:','To evaluate the consequences of decisions made by identifying what a different choice would have produced.','[''To predict future government behavior'',''To evaluate the consequences of decisions made by identifying what a different choice would have produced.'',''To express uncertainty about whether the approach was comprehensive'',''To recommend that the government adopt a different approach in the future'']','Type 3 counterfactual = retrospective evaluation of actual decision by comparing it to the alternative. Academic critique function.','easy'),
  (cid,75,237,'gap_fill','[TOEFL Reading] ''If the institution _____ (design) _____ differently, it _____ (not/now/face) _____ the same structural constraints.'' Best forms for a mixed conditional?','had been designed / would not now be facing',NULL,'Mixed conditional: Type 3 if-clause ''had been designed'' + Type 2 result ''would not now be facing.''','medium'),
  (cid,75,238,'gap_fill','[TOEFL Reading] ''Unless _____ (substantially/revise/passive), the framework _____ (likely/fail) to address the emerging challenges.'' Best forms?','substantially revised / is likely to fail',NULL,'''Unless substantially revised'' (omitted subject = if it is not) + ''is likely to fail'' = real conditional (Type 1/Type 0).','medium'),
  (cid,75,239,'multiple_choice','[TOEFL Reading] ''Should the proposal be adopted, the implementation challenges would be considerable.'' The modal ''would'' tells us:','The speaker considers adoption uncertain or hypothetical.','[''The speaker is certain adoption will happen'',''The speaker considers adoption uncertain or hypothetical.'',''The speaker recommends against adoption'',''The proposal has already been adopted'']','Inverted Type 2 ''Should the proposal be adopted'' = hypothetical future. ''Would be'' = uncertain/hypothetical result.','easy'),
  (cid,75,240,'gap_fill','[TOEFL Reading] ''If the actors involved _____ (act) _____ on short-term incentives alone, the cooperative arrangement _____ (collapse) _____ long ago.'' Best forms?','had acted / would have collapsed',NULL,'Type 3: ''If actors had acted on short-term incentives, would have collapsed'' = they didn''t act that way, so cooperation persisted.','medium'),
  (cid,75,241,'gap_fill','[TOEFL Reading] ''The system _____ (not/function) _____ as effectively as it does had _____ (the) _____ designers _____ (not/anticipate) _____ these failure modes.'' Best inversion?','would not function / the / designers / not anticipated',NULL,'Inverted Type 3: ''would not function'' + ''had designers not anticipated'' for design counterfactual.','medium'),

  -- BLOCK 76: TOEFL Speaking com condicionais tipos 2 e 3
  (cid,76,242,'production','[TOEFL Speaking — 45s] A reading describes why a reform failed. Use Type 3 conditionals to explain what would have needed to happen for it to succeed.','',NULL,'The reading describes a reform that failed to achieve its objectives, and several Type 3 conditionals help clarify what would have been needed for a different outcome. Had the reformers secured support from the key stakeholder groups from the outset — rather than attempting to proceed over their opposition — implementation would have been substantially smoother. If the government had provided adequate resources for the implementing agencies, those agencies would not have been forced to make the compromises that ultimately undermined the reform''s fidelity. Had the monitoring mechanisms been designed with real consequences for non-compliance rather than simply reporting requirements, the deviations from the intended design that occurred during implementation might have been caught and corrected earlier. And had the reform been introduced more gradually, allowing for learning and adjustment, it would probably have survived the political challenges that ultimately reversed it. The reading''s implicit argument is that the reform failed not because its objectives were wrong but because the political and administrative conditions necessary for its success were never adequately secured.','hard'),
  (cid,76,243,'production','[TOEFL Speaking — 45s] The professor discusses a researcher who made a methodological error early in her career. Use conditionals to explain the consequences.','',NULL,'The professor discusses a case that illustrates how early methodological choices shape the trajectory of a research program. She describes a researcher who, early in her career, adopted a data collection approach that seemed efficient at the time but that subsequently proved to introduce systematic biases into her findings. Had she used a different approach, her conclusions would have been more reliable — but because the methodological choice was embedded in a large longitudinal study, it was very difficult to change course after the initial data collection had begun. If the researcher had consulted with methodologists before designing the study, she might have identified the problem before committing to an approach that proved difficult to defend. As it was, the researcher spent much of her subsequent career either defending or attempting to correct for the methodological limitations, which significantly constrained the program''s productivity. The professor uses this case to argue that the investment of time and resources in rigorous upfront design, even when it delays the start of data collection, is almost always justified — because the costs of methodological problems, should they prove to have been avoidable, are typically much greater than the costs of doing the design work well in the first place.','hard'),
  (cid,76,244,'production','[TOEFL Speaking — 60s] Compare what the reading and professor say about what determines whether institutions succeed or fail, using conditionals throughout.','',NULL,'The reading and the professor both use conditional reasoning to argue about what determines institutional success and failure, but they draw different lessons. The reading uses Type 3 conditionals to make counterfactual arguments about the institutions it examines: it argues that had these institutions been designed with clearer mandates and more robust accountability mechanisms, they would have performed significantly better. It suggests that if the founders had anticipated the political pressures the institutions would face, they would have built in stronger protections against capture and mission drift. The reading''s argument is essentially retrospective — it uses what would have happened under different design choices to illuminate what went wrong with the actual choices. The professor accepts this logic but argues that it misses something important: that if we only examine cases of failure, we will underestimate how much institutional performance depends on factors that cannot be designed in advance, such as the quality of leadership, the culture that develops over time, and the specific political context in which the institution operates. She argues that had the reading included comparative analysis of institutions with similar designs but very different performance outcomes, it would have found that design explains much less variance than it appears to when examined in isolation. Her conclusion is not that design doesn''t matter — it would be foolish to ignore it — but that institutional success requires more than good design, and that if we treat design as sufficient, we will systematically underinvest in the non-design factors that often matter more.','hard'),
  (cid,76,245,'gap_fill','[TOEFL Speaking] If _____ (the) _____ _____ (professor) _____ _____ (argue) _____ as _____ (the) _____ reading _____ _____ (suggest), _____ _____ (she) _____ _____ (would/overlook) _____ (the) _____ institutional _____ _____ (factor) that _____ _____ (her) _____ _____ (own/research/have) _____ _____ (identify) _____ as _____ critical — _____ hence _____ _____ (her) _____ _____ (qualification).','If / the / professor / were to argue / as / the / reading / suggests / she / would overlook / the / institutional / factors / that / her / own research / has / identified / as / critical / hence / her / qualification',NULL,'Type 2 ''If were to argue...would overlook'' for professor''s deviation from reading argument.','hard'),

  -- BLOCK 77: TOEFL Writing com condicionais tipos 2 e 3
  (cid,77,246,'production','[TOEFL Writing — 200 words] Write a paragraph on what accountability mechanisms would look like if they were designed optimally, using Type 2 conditionals.','',NULL,'If accountability mechanisms were designed optimally, they would exhibit several characteristics that are rarely found together in practice. They would set clear and measurable standards against which performance could be assessed, so that those responsible for outcomes could neither claim credit for successes they did not produce nor evade responsibility for failures they could have prevented. They would provide information to relevant audiences in forms they could actually use, rather than producing reports that satisfied a formal requirement without enabling genuine oversight. If the mechanisms were designed with genuine transparency in mind, they would make the reasoning behind decisions visible, so that those scrutinizing the decisions could assess not only whether the outcomes were satisfactory but whether the process by which they were reached was sound. They would be timely: if feedback arrived quickly enough to allow course correction, many of the problems that currently develop over extended periods without effective response could be identified and addressed earlier. They would also be independent of those being held accountable, because if the evaluated set their own standards and assessed their own performance, the entire exercise would be compromised. And they would carry real consequences for poor performance, because if non-compliance with standards had no meaningful effect on those responsible, the standards themselves would function only as aspirational statements rather than as genuine constraints on behavior.','hard'),
  (cid,77,247,'production','[TOEFL Writing — 200 words] Write a body paragraph on what would have needed to happen for a particular international agreement to succeed, using Type 3 conditionals.','',NULL,'For the agreement to have succeeded, several conditions that were absent would have needed to be present. Had the negotiating parties designed the monitoring mechanisms with genuine rigor rather than accepting the vague reporting requirements that political compromise demanded, it would have been much easier to identify non-compliance early and to apply pressure for correction before deviations from commitments became entrenched. If the agreement had included an independent review mechanism — one insulated from political pressure by the major parties — it would have generated the kind of authoritative assessments that could have mobilized public opinion in ways that made governments'' commitments politically difficult to abandon. Had the parties also included graduated response mechanisms, so that escalating levels of non-compliance triggered escalating consequences, actors who calculated that the benefits of defection outweighed the costs of compliance might have calculated differently. And if the agreement had built in a structured review process through which its targets could be updated as scientific understanding evolved and as new information about feasibility became available, the rigidity that eventually made some parties feel that their only option was withdrawal would have been avoided. None of these design choices would have guaranteed success — politics and domestic pressures would still have created significant headwinds — but they would have substantially improved the agreement''s odds.','hard'),
  (cid,77,248,'gap_fill','[TOEFL Writing] The _____ _____ (argument) _____ _____ (stronger/be/would) _____ had _____ _____ (the) _____ _____ (authors) _____ _____ (engage) _____ more _____ _____ (directly) _____ with _____ _____ the _____ _____ (alternative) _____ _____ (explanation) _____ _____ that _____ _____ (their) _____ _____ (evidence) does _____ not _____ _____ (conclusively/rule/out).','The / argument / would be stronger / had / the / authors / engaged / more / directly / with / the / alternative / explanations / that / their / evidence / does / not / conclusively / rule out',NULL,'Type 3 ''would be stronger had the authors engaged'' for academic critique.','medium'),
  (cid,77,249,'gap_fill','[TOEFL Writing] If _____ (the) _____ _____ (evidence) _____ _____ (available/were) _____ to _____ _____ (support) _____ a _____ _____ (more/definitive) _____ _____ (conclusion), _____ (this) _____ _____ (analysis) _____ _____ (would/offer) _____ one — _____ _____ (but/as/it) _____ _____ (is), _____ _____ the _____ _____ (most) _____ _____ (that) _____ _____ (can/say/passive) _____ _____ (be) _____ _____ (that) _____ the _____ _____ (current) _____ _____ (balance) of _____ evidence _____ _____ (favor) _____ the _____ _____ (proposed) _____ _____ (interpretation).','If / the / evidence / were available / to / support / a / more definitive / conclusion / this / analysis / would offer / one / but as it / is / the / most / that / can be said / is / that / the / current / balance / of / evidence / favors / the / proposed / interpretation',NULL,'Type 2 ''If evidence were available, would offer'' for epistemic hedging in academic writing.','hard'),
  (cid,77,250,'gap_fill','[TOEFL Writing] Had _____ _____ (this) _____ _____ (study) _____ _____ (include) _____ _____ (a) _____ _____ (longitudinal) _____ _____ (component), _____ _____ (it) _____ _____ (have/would/been/able) _____ to _____ _____ (track) _____ _____ (the) _____ _____ (change) _____ over _____ _____ (time) _____ that _____ _____ (the) _____ cross-sectional _____ _____ (design) _____ _____ (can/capture/not).','Had / this / study / included / a / longitudinal / component / it / would have been able / to / track / the / changes / over / time / that / the / cross-sectional / design / cannot capture',NULL,'Type 3 ''Had included, would have been able to track'' for research design limitation acknowledgment.','medium'),
  (cid,77,251,'gap_fill','[TOEFL Writing] The _____ _____ (reform) _____ _____ (might/succeed/have) _____ if _____ _____ (the) _____ _____ (political) _____ _____ (window/had/longer/been) — _____ _____ (but) _____ _____ (windows) _____ _____ (close), _____ and _____ _____ (the) _____ _____ (lesson) _____ _____ (may/be) _____ that _____ _____ (reform) _____ _____ (must) _____ _____ (design) for _____ _____ (the) _____ _____ (time) _____ available, _____ not _____ _____ (for) _____ _____ (the) _____ _____ (time) _____ _____ (needed/might/one/wish).','The / reform / might have succeeded / if / the / political / window / had been longer / but / windows / close / the / lesson / may be / that / reform / must be designed / for / the / time / available / not / for / the / time / one might wish / needed',NULL,'Type 3 ''might have succeeded if had been longer'' for reform political window analysis.','hard'),
  (cid,77,252,'gap_fill','[TOEFL Writing] If _____ _____ (we) _____ _____ (take) _____ _____ (the) _____ _____ (evidence) _____ at _____ _____ (face/value), _____ _____ (we) _____ _____ (would/conclude) _____ that _____ _____ (the) _____ _____ (intervention) _____ _____ (work) — _____ _____ (but) _____ _____ (the) _____ _____ (inferential) _____ _____ (leap) from _____ _____ (observed/association) _____ to _____ _____ (causal) _____ _____ (claim) _____ is _____ one _____ that _____ _____ (the/data/cannot/make).','If / we / took / the / evidence / at / face value / we / would conclude / that / the / intervention / works / but / the / inferential / leap / from / observed associations / to / causal / claims / is / one / that / the data / cannot make',NULL,'Type 2 ''If we took, would conclude'' + ''but the data cannot make'' for causal inference caution.','hard'),

  -- BLOCK 78: Gap fills avançados com condicionais
  (cid,78,253,'gap_fill','If _____ (the) _____ _____ (institutions) _____ _____ (design/had/passive) _____ to _____ _____ (reward) _____ _____ (long-term) _____ _____ (thinking) rather than _____ _____ (short-term) _____ _____ (performance), _____ _____ (the) _____ _____ (individual) _____ _____ (incentive) _____ _____ (would/align/have) _____ more _____ _____ (closely) _____ with _____ _____ (collective) _____ _____ (welfare) — _____ _____ (a) _____ _____ (observation) _____ _____ (with) _____ _____ (profound) _____ _____ (implication) for _____ _____ (institutional) _____ _____ (design).','If / the / institutions / had been designed / to / reward / long-term / thinking / rather / short-term / performance / the / individual / incentives / would have aligned / more / closely / with / collective / welfare / a / observation / with / profound / implications / institutional / design',NULL,'Type 3 ''If had been designed, would have aligned'' for incentive alignment institutional argument.','hard'),
  (cid,78,254,'gap_fill','Were _____ (it) _____ _____ (not/for) _____ _____ (the) _____ _____ (constraints) _____ _____ (impose/passive) _____ by _____ _____ (the) _____ _____ (constitutional) _____ _____ (framework), _____ _____ (the) _____ _____ (executive) _____ _____ (act/might) _____ with _____ _____ (far/greater) _____ unilateral _____ _____ (authority) — _____ _____ (a) _____ _____ (fact) _____ that _____ _____ (underscores) _____ _____ (the) _____ _____ (importance) of _____ _____ (constitutional) _____ _____ (design).','Were / it / not / for / the / constraints / imposed / by / the / constitutional / framework / the / executive / might act / with / far greater / unilateral / authority / a / fact / that / underscores / the / importance / constitutional / design',NULL,'''Were it not for constraints, might act'' for constitutional constraint analysis.','hard'),
  (cid,78,255,'gap_fill','If _____ (this) _____ _____ (trend) _____ _____ (continue), _____ _____ (the) _____ _____ (long-term) _____ _____ (consequence) _____ _____ (serious/be/would) — _____ _____ (but) _____ _____ (if) _____ _____ (the) _____ _____ (necessary) _____ _____ (adjustment) _____ _____ (make/were/passive), _____ _____ (the) _____ _____ (outcome) _____ _____ (significantly/could/improve/passive).','If / this / trend / were to continue / the / long-term / consequences / would be serious / but / if / the / necessary / adjustments / were made / the / outcomes / could be significantly improved',NULL,'Double Type 2: ''If trend were to continue/were made'' for policy scenario analysis.','hard'),
  (cid,78,256,'gap_fill','Had _____ _____ (the) _____ _____ (warning) _____ _____ (taken/passive) _____ _____ (more/seriously), _____ _____ the _____ _____ (crisis) _____ _____ (avoid/might/passive) — _____ _____ (but) _____ _____ (by) _____ the _____ _____ (time) _____ _____ (the) _____ _____ (severity) of _____ _____ (the) _____ _____ (problem) _____ _____ (apparent/became), _____ _____ (the) _____ _____ (window) _____ for _____ _____ (prevention) _____ _____ (close/had).','Had / the / warnings / been taken / more / seriously / the / crisis / might have been avoided / but / by / the / time / the / severity / of / the / problem / became apparent / the / window / for / prevention / had closed',NULL,'Type 3 ''Had warnings been taken, might have been avoided'' + ''by the time apparent, had closed.''','hard'),
  (cid,78,257,'gap_fill','The _____ _____ (outcome) _____ _____ (been/have/would/different) _____ if _____ _____ (the) _____ _____ (conditions) _____ _____ (under/which) _____ _____ the _____ _____ (decision) _____ _____ (make/was) _____ _____ (different/had/been) — _____ _____ (a) _____ _____ (observation) _____ _____ (that) _____ _____ (trivially/is/true) _____ _____ (but) _____ _____ (that) _____ _____ (nonetheless/reveals) _____ _____ (the) _____ _____ (degree) _____ to _____ which _____ _____ (outcome) _____ _____ (path-dependent/are).','The / outcome / would have been different / if / the / conditions / under which / the / decision / was made / had been different / a / observation / that / is trivially true / but / that / nonetheless reveals / the / degree / to which / outcomes / are path-dependent',NULL,'Type 3 ''would have been different if had been different'' for path dependency analysis.','hard'),
  (cid,78,258,'multiple_choice','Which conditional structure MOST appropriately concludes an academic argument about institutional failure?','Had the accountability mechanisms been more robust, the pattern of behavior that ultimately led to the crisis might have been identified and corrected before it became entrenched.','[''If the accountability mechanisms are more robust, the crisis would have been avoided.'',''The crisis would be avoided if the accountability mechanisms would be more robust.'',''Had the accountability mechanisms been more robust, the pattern of behavior that ultimately led to the crisis might have been identified and corrected before it became entrenched.'',''If the accountability mechanisms had been more robust, the crisis might avoid.'']','Type 3 inverted ''Had been more robust, might have been identified and corrected'' = most accurate and formal for retrospective analysis.','medium'),
  (cid,78,259,'gap_fill','If _____ _____ (the) _____ _____ (analysis) _____ _____ (shown/had) _____ _____ (different) _____ _____ (result), _____ _____ (the) _____ _____ (conclusion) _____ _____ (would/been/have) _____ different _____ too — _____ (and) _____ _____ (the) _____ _____ (willingness) to _____ _____ (follow) _____ _____ (the) _____ _____ (evidence) _____ _____ (wherever/leads) it, _____ rather _____ than _____ _____ (fit) _____ it _____ to _____ _____ (prior) _____ _____ (expectation), _____ _____ (what/be) _____ _____ (distinguishes) _____ _____ (rigorous) _____ _____ (inquiry) _____ from _____ _____ (advocacy).','If / the / analysis / had shown / different / results / the / conclusions / would have been / different / too / the / willingness / to / follow / the / evidence / wherever / it / leads / rather / fitting / it / prior / expectations / is what / distinguishes / rigorous / inquiry / advocacy',NULL,'Type 3 ''If had shown, would have been'' for academic integrity argument.','hard'),

  -- BLOCK 79: Produção avançada — condicionais tipos 2 e 3
  (cid,79,260,'production','[TOEFL Writing — 200 words] Write a body paragraph on what would happen if democratic institutions were weakened, using Type 2 conditionals throughout.','',NULL,'If democratic institutions were significantly weakened, the consequences for governance and human welfare would be far-reaching. If the independence of the judiciary were compromised, those with political power would be able to use legal mechanisms to pursue opponents and protect allies, eroding the rule of law that protects everyone equally regardless of their standing with those in power. Were the press to lose its independence, the information environment in which citizens form their political judgments would be shaped by those who control access, making it far more difficult to hold power accountable for its decisions and performance. If electoral systems were manipulated to the point that they no longer reliably translated the preferences of the electorate into political outcomes, the fundamental mechanism through which democratic accountability operates would be undermined. Were civil society organizations restricted in their ability to organize and advocate, the capacity of those outside formal institutions to contest decisions, mobilize opposition, and propose alternatives would be severely curtailed. And if all of these conditions obtained simultaneously — as they do in countries undergoing rapid democratic backsliding — the cumulative effect would be an environment in which those holding power faced very few meaningful constraints on its exercise, which historical experience suggests consistently produces poor outcomes for governance quality and human welfare.','hard'),
  (cid,79,261,'production','[TOEFL Writing — 200 words] Write a paragraph using Type 3 conditionals to evaluate a historical policy decision.','',NULL,'The decision to prioritize speed over consultation in the design of the reform was a consequential one whose costs became apparent only over time. Had the designers invested more time in engaging the stakeholder groups most affected by the proposed changes, they would have learned about implementation constraints that the central design team was unaware of — constraints that ultimately derailed what had appeared, from the center, to be a technically sound proposal. If the reform had been piloted in a small number of jurisdictions before being scaled nationally, the design problems would have surfaced at a scale at which they could be corrected without triggering the political backlash that national rollout of a flawed design provoked. Had the monitoring system been designed to detect implementation problems early — rather than to confirm that the process was on track according to formal indicators that turned out not to capture what actually mattered — the decision-makers would have received the warning signals they needed to authorize design modifications before the problems became public and politically sensitive. None of these choices would have guaranteed success: the reform was attempting something genuinely difficult, and there would have been challenges regardless of process. But had the process been better, the probability of success would have been substantially higher, and the costs of the eventual failure would have been significantly lower.','hard'),
  (cid,79,262,'gap_fill','[TOEFL Writing] Had _____ _____ (we) _____ _____ (approach) _____ _____ (the) _____ _____ (question) _____ _____ (differently), _____ _____ (we) _____ _____ (might/have/arrive) _____ at _____ _____ (different) _____ _____ (conclusion) — _____ _____ (but) _____ _____ (the) _____ _____ (framing) _____ _____ (choose/passive) _____ _____ (is/not) _____ _____ (arbitrary): it _____ _____ (reflect) _____ _____ (the) _____ _____ (theoretical) _____ _____ (commitment) _____ _____ (that) _____ _____ (give) _____ _____ (the) _____ _____ (analysis) _____ _____ (its) _____ _____ (coherence).','Had / we / approached / the / question / differently / we / might have arrived / at / different / conclusions / but / the / framing / chosen / is not / arbitrary / it / reflects / the / theoretical / commitments / that / give / the / analysis / its / coherence',NULL,'Type 3 ''Had approached, might have arrived'' for reflexive methodology statement.','medium'),
  (cid,79,263,'gap_fill','[TOEFL Writing] If _____ _____ (the) _____ _____ (evidence) _____ _____ (stronger/were), _____ _____ (a) _____ _____ (more/confident) _____ _____ (claim) _____ _____ (justify/be/would) — _____ _____ (but) _____ _____ (epistemic) _____ _____ (honesty) _____ _____ (require) _____ _____ (acknowledging) _____ _____ (the) _____ _____ (limits) of _____ _____ (what) _____ _____ (the) _____ _____ (data) can _____ _____ (and/cannot/support).','If / the / evidence / were stronger / a / more confident / claim / would be justified / but / epistemic / honesty / requires / acknowledging / the / limits / of / what / the / data / can / and cannot / support',NULL,'Type 2 ''If evidence were stronger, would be justified'' for hedged academic claim.','medium'),
  (cid,79,264,'gap_fill','[TOEFL Writing] Even _____ _____ if _____ _____ (the) _____ _____ (most) _____ _____ (ambitious) _____ _____ (reform) _____ _____ (attempt/passive), _____ _____ (it) _____ _____ (not/guarantee/would) _____ _____ (success) — _____ _____ (but) _____ _____ (without) _____ _____ (ambition), _____ _____ (the) _____ _____ (outcome) _____ _____ (guaranteed/is) _____ _____ (to) _____ _____ (disappoint).','Even / if / the / most / ambitious / reform / were attempted / it / would not guarantee / success / but / without / ambition / the / outcome / is guaranteed / to / disappoint',NULL,'Type 2 ''Even if were attempted, would not guarantee'' for reform ambition argument.','hard'),
  (cid,79,265,'gap_fill','[TOEFL Writing] This _____ _____ (be) _____ _____ (a) _____ _____ (case) _____ _____ (in/which) _____ _____ (more) _____ _____ (data) _____ _____ (not/necessarily/yield) _____ _____ (better) _____ _____ (insight) — _____ _____ (what) _____ _____ (need) is _____ _____ (not) _____ _____ (more) _____ _____ (data) _____ but _____ _____ (a) _____ _____ (better) _____ _____ (framework) for _____ _____ (interpret) _____ _____ (the) _____ _____ (data) _____ _____ (already/have/passive).','This / is / a / case / in which / more / data / would not necessarily yield / better / insight / what / is needed / is / not / more / data / but / a / better / framework / for / interpreting / the / data / already had',NULL,'Type 2 ''would not necessarily yield'' for epistemological argument about data vs. framework.','hard'),

  -- BLOCK 80: Gap fills — condicionais em contexto científico e de políticas
  (cid,80,266,'gap_fill','If _____ _____ (the) _____ _____ (model) _____ _____ (work) _____ as _____ _____ (specify/passive), _____ _____ (we) _____ _____ (would/expect) _____ to _____ _____ (observe) _____ _____ (a) _____ _____ (specific) _____ _____ (pattern) _____ in _____ _____ (the) _____ _____ (data) — _____ _____ (the) _____ _____ (fact) _____ that _____ _____ (we) _____ _____ (do) _____ not _____ _____ (observe) _____ it _____ _____ (constitute) _____ _____ (evidence) _____ _____ (against) _____ _____ (the) _____ _____ (model).','If / the / model / worked / as / specified / we / would expect / to / observe / a / specific / pattern / in / the / data / the / fact / that / we / do / not / observe / it / constitutes / evidence / against / the / model',NULL,'Type 2 ''If model worked, would expect'' for falsification logic in scientific reasoning.','hard'),
  (cid,80,267,'gap_fill','Had _____ _____ (the) _____ _____ (experiment) _____ _____ (design/passive) _____ with _____ _____ (a) _____ _____ (control) _____ _____ (group), _____ _____ (it) _____ _____ (have/would/possible/been) _____ to _____ _____ (isolate) _____ _____ (the) _____ _____ (effect) _____ of _____ _____ (the) _____ _____ (intervention) _____ from _____ _____ (the) _____ _____ (other) _____ _____ (factor) _____ that _____ _____ (may/have/influence) _____ _____ (the) _____ _____ (outcome).','Had / the / experiment / been designed / with / a / control / group / it / would have been possible / to / isolate / the / effect / of / the / intervention / from / the / other / factors / that / may have influenced / the / outcome',NULL,'Type 3 ''Had been designed, would have been possible to isolate'' for experimental design critique.','hard'),
  (cid,80,268,'gap_fill','If _____ _____ (the) _____ _____ (same) _____ _____ (pattern) _____ _____ (observe/passive) _____ _____ (across) _____ _____ (multiple) _____ _____ (independent) _____ _____ (study), _____ _____ (the) _____ _____ (confidence) in _____ _____ (the) _____ _____ (finding) _____ _____ (substantially/increase/would) — _____ _____ (but) _____ _____ (replication/the) _____ _____ (crisis) _____ _____ (has/shown) _____ that _____ _____ (many) _____ _____ (published) _____ _____ (result) _____ _____ (not/do) _____ _____ (replicate).','If / the / same / pattern / were observed / across / multiple / independent / studies / the / confidence / in / the / finding / would substantially increase / but / the replication / crisis / has shown / that / many / published / results / do / not / replicate',NULL,'Type 2 ''If were observed across studies, would increase'' for replication and scientific confidence.','hard'),
  (cid,80,269,'gap_fill','Had _____ _____ (the) _____ _____ (program) _____ _____ (include) _____ _____ (more) _____ _____ (rigorous) _____ _____ (evaluation) _____ _____ (component), _____ _____ (the) _____ _____ (evidence) _____ on _____ _____ (which) _____ _____ (expansion) _____ _____ (decision/base/passive) _____ _____ (much/stronger/be/would/have) — _____ _____ (instead), _____ _____ (the) _____ _____ (expansion) _____ _____ (proceed/did) on _____ _____ (the) _____ _____ (basis) of _____ _____ (limited) _____ _____ (evidence) _____ whose _____ _____ (credibility) _____ was _____ _____ (dispute).','Had / the / program / included / more / rigorous / evaluation / components / the / evidence / on which / expansion / decisions / were based / would have been much stronger / instead / the / expansion / proceeded / on / the / basis / limited / evidence / whose / credibility / was / disputed',NULL,'Type 3 ''Had included, would have been stronger'' for program evaluation design critique.','hard'),
  (cid,80,270,'gap_fill','If _____ _____ (the) _____ _____ (peer) _____ _____ (review) _____ _____ (process) _____ _____ (adequately/screen) _____ for _____ _____ (methodological) _____ _____ (quality), _____ _____ (many) of _____ _____ (the) _____ _____ (finding) that _____ _____ (now/dominate) _____ _____ (the) _____ _____ (literature) _____ _____ (not/publish/would) — _____ _____ (a) _____ _____ (troubling) _____ _____ (observation) _____ _____ (for/those) _____ _____ (who) _____ _____ (rely) on _____ _____ (peer) _____ _____ (review) as _____ _____ (a) _____ _____ (quality) _____ _____ (signal).','If / the / peer / review / process / adequately screened / for / methodological / quality / many / the / findings / that / now dominate / the / literature / would not have been published / a / troubling / observation / for those / who / rely / on / peer / review / as / a / quality / signal',NULL,'Type 2/3 ambiguous ''If adequately screened, would not have been published'' for peer review critique.','hard'),
  (cid,80,271,'multiple_choice','Which conditional best expresses a policy lesson from a historical failure?','Had the designers consulted the implementing agencies, the operational infeasibility of the proposal would have been identified before, rather than after, substantial resources were committed.','[''If the designers consult the implementing agencies, the operational infeasibility of the proposal would be identified.'',''Had the designers consulted the implementing agencies, the operational infeasibility of the proposal would have been identified before, rather than after, substantial resources were committed.'',''If the designers would have consulted the implementing agencies, the operational infeasibility of the proposal would be identified.'',''The designers should have consulted the implementing agencies if they would identify operational infeasibility.'']','Type 3 inverted ''Had consulted, would have been identified'' = most accurate retrospective policy lesson.','easy'),
  (cid,80,272,'gap_fill','If _____ _____ (only) _____ _____ (the) _____ _____ (problem) _____ _____ (were) _____ as _____ _____ (simple) as _____ _____ (the) _____ _____ (diagnosis) _____ _____ (suggest), _____ _____ (the) _____ _____ (solution) _____ _____ (straightforward/would/be) _____ — _____ _____ (but) _____ _____ (the) _____ _____ (gap) _____ between _____ _____ (the) _____ _____ (simplified) _____ _____ (model) _____ and _____ _____ (the) _____ _____ (messy) _____ _____ (reality) _____ _____ (is/where) _____ _____ (most) _____ _____ (policy) _____ _____ (intervention) _____ _____ (fail).','If / only / the / problem / were / as / simple / as / the / diagnosis / suggests / the / solution / would be straightforward / but / the / gap / between / the / simplified / model / and / the / messy / reality / is where / most / policy / interventions / fail',NULL,'''If only the problem were...would be'' (Type 2 wish/lament) for policy complexity argument.','hard'),
  (cid,80,273,'gap_fill','We _____ _____ (make) _____ _____ (different) _____ _____ (choice) _____ _____ (now) _____ _____ (if) _____ _____ (we) _____ _____ (know) _____ _____ (then) _____ _____ (what) _____ _____ (we) _____ _____ (know/now) — _____ _____ (but) _____ _____ (this) _____ _____ (observation) _____ _____ (is) _____ _____ (not/simply) _____ _____ (an/excuse): it _____ _____ (is) _____ _____ (an) _____ _____ (invitation) _____ to _____ _____ (learn) _____ from _____ _____ (the) _____ _____ (gap) _____ between _____ _____ (expectation) _____ and _____ _____ (outcome).','would have made / different / choices / then / if / we / had known / then / what / we / know now / but / this / observation / is / not simply / an excuse / it / is / an / invitation / to / learn / from / the / gap / between / expectations / outcomes',NULL,'Mixed conditional ''would have made different choices if had known'' for organizational learning argument.','hard'),

  -- BLOCK 81: Exercícios finais
  (cid,81,274,'production','[TOEFL Speaking — 45s] The professor discusses the consequences of a governmental failure to act. Use Type 3 conditionals throughout.','',NULL,'The professor argues that the government''s failure to act during the critical window represents one of the most consequential decisions of the period. Had the government intervened when the early warning indicators first appeared, it would have been dealing with a problem that was still manageable in scale. If the initial response had been proportionate to the severity of the emerging threat rather than calibrated to minimize political disruption, the subsequent escalation that required a far more expensive and disruptive response might have been avoided. Had the institutional mechanisms for early warning been better integrated with the decision-making processes that could authorize a response, the information that was available to technical experts would have reached political decision-makers in time to make a difference. And if the government had invested earlier in the response capacity that was needed but not available when the crisis accelerated, it would not have faced the constraints that forced it into choices between inadequate options. The professor concludes that each of these failures was individually remediable and collectively preventable, and that the fact that they occurred simultaneously reflects a systemic failure of governance rather than simply a series of individual errors.','hard'),
  (cid,81,275,'production','[TOEFL Speaking — 60s] Compare what the reading and professor say about innovation adoption using Type 2 conditionals.','',NULL,'Both the reading and the professor use conditional reasoning to explain why innovation adoption is slower than the quality of available innovations would seem to warrant, though they identify different bottlenecks. The reading argues that if organizations had better information about the returns to innovation — including more reliable data on implementation costs, learning curves, and context-specific adaptation requirements — they would be more willing to take the risks that adoption entails. It suggests that if the information environment surrounding innovation were less skewed toward success stories and more representative of the full distribution of outcomes, including failures, organizations would make more realistic assessments and avoid the disappointment that follows adoption of innovations whose real-world performance falls short of what promotional materials suggest. The professor accepts this but argues that even if organizations had perfect information, many would still underinvest in innovation because of structural features of how they operate and how their leaders are incentivized. She argues that if organizations were able to reward the experiments that fail informatively as well as those that succeed, they would generate much more learning and much more genuine innovation. And if the individuals responsible for innovation decisions were evaluated over time horizons long enough to observe the full consequences of their choices, rather than on annual or quarterly performance metrics, they would be more willing to make the investments in capability building and organizational change that durable innovation requires. Her conclusion is that better information would help, but that without structural changes in incentives, its impact would be modest.','hard'),
  (cid,81,276,'gap_fill','[TOEFL Writing] The _____ _____ (situation) _____ _____ (were) _____ _____ (different), _____ _____ (this) _____ _____ (analysis) _____ _____ (arrive/might/have) _____ at _____ _____ (a) _____ _____ (different) _____ _____ (conclusion) — _____ _____ (but) _____ _____ (the) _____ _____ (analysis) _____ _____ (cannot) _____ _____ (proceed) _____ from _____ _____ (the) _____ _____ (situation) _____ _____ (as) _____ _____ (we) _____ _____ (wish) _____ it _____ _____ (were), _____ _____ only _____ from _____ _____ (the) _____ _____ (situation) _____ _____ (as) _____ _____ (it) _____ _____ (is).','If the / situation / were / different / this / analysis / might have arrived / at / a / different / conclusion / but / the / analysis / cannot / proceed / from / the / situation / as / we / wish / it / were / only / from / the / situation / as / it / is',NULL,'Mixed conditional for distinguishing idealized from actual context in analysis.','hard'),
  (cid,81,277,'gap_fill','[TOEFL Writing] If _____ _____ (we) _____ _____ (not/constrain/passive) _____ by _____ _____ (the) _____ _____ (need) to _____ _____ (reach) _____ _____ (a) _____ _____ (conclusion) that _____ _____ (can/communicate/passive) _____ _____ (briefly), _____ _____ (the) _____ _____ (full) _____ _____ (complexity) of _____ _____ (the) _____ _____ (argument) _____ _____ (occupy/might) _____ _____ (several) _____ _____ (volume) — _____ _____ (a) _____ _____ (reminder) _____ that _____ _____ (simplification) _____ _____ (is/always) _____ _____ (a) _____ _____ (necessary) _____ _____ (loss).','If / we / were not constrained / by / the / need / to / reach / a / conclusion / that / can be communicated / briefly / the / full / complexity / the / argument / might occupy / several / volumes / a / reminder / that / simplification / always is / a / necessary / loss',NULL,'Type 2 ''If not constrained, might occupy'' for reflexive meta-argument about academic writing constraints.','hard'),
  (cid,81,278,'gap_fill','[TOEFL Writing] In _____ _____ (sum), _____ _____ (the) _____ _____ (evidence) _____ _____ (suggest) _____ that _____ _____ (the) _____ _____ (outcome) _____ _____ (have/been/would/better) _____ had _____ _____ (the) _____ _____ (approach) _____ _____ (been) _____ _____ (more/comprehensive) — _____ _____ (a) _____ _____ (lesson) _____ that _____ _____ (inform) _____ _____ (should) _____ _____ (the) _____ _____ (design) of _____ _____ (future) _____ _____ (intervention).','In / sum / the / evidence / suggests / that / the / outcomes / would have been better / had / the / approach / been / more comprehensive / a / lesson / that / should inform / the / design / future / interventions',NULL,'Type 3 ''would have been better had been more comprehensive'' for academic conclusion.','medium'),
  (cid,81,279,'gap_fill','[TOEFL Writing] _____ _____ (the) _____ _____ (approach) _____ _____ (were) _____ _____ (to) _____ _____ (address) _____ _____ (all) _____ _____ (these) _____ _____ (concern), _____ _____ (it) _____ _____ (would/require) _____ _____ (resources) _____ and _____ _____ (political) _____ _____ (will) _____ that _____ _____ (currently) _____ _____ (available/not/are) — _____ _____ (a) _____ _____ (sobering) _____ _____ (constraint) _____ on _____ _____ (what) _____ _____ (can) _____ _____ (achieve/passive) _____ in _____ _____ (the) _____ _____ (near) _____ _____ (term).','If the / approach / were / to / address / all / these / concerns / it / would require / resources / political / will / that / are not currently / available / a / sobering / constraint / on / what / can / be achieved / in / the / near / term',NULL,'Type 2 ''If were to address, would require'' for pragmatic policy conclusion.','hard'),
  (cid,81,280,'production','[TOEFL Writing — 200 words] Write a conclusion using mixed conditionals on what better institutional design could have produced and still can produce.','',NULL,'The analysis of institutional failure undertaken here supports a clear but sobering conclusion: had the design choices made at the outset been different — had the architects of the institution attended more carefully to the incentive problems that would arise as the institution scaled and as the political environment shifted — much of the performance deficit we observe today would have been avoidable. The institution would currently be operating with a track record of effectiveness that would have given it the political and reputational capital to weather the challenges it now faces from a position of weakness. That opportunity has passed, and no amount of retrospective wisdom can recover it. But the same analytical framework that illuminates what went wrong also points toward what is still possible. If the institution were to undertake a genuine reform of its governance and accountability structures — not the incremental adjustments that have been offered as reform in the past, but the structural changes that address the root causes of poor performance — it would be in a much stronger position within a decade. Had previous reform efforts been more ambitious, we would not need to make this argument today. But the case for ambition now is precisely that a further decade of inadequate reform would leave the institution in a position from which recovery would be far more difficult. The window for effective institutional repair is narrowing; the cost of failing to act is rising; and the conditional logic of reform is clear.','hard'),

  -- BLOCK 82: Últimos exercícios finais
  (cid,82,281,'gap_fill','[TOEFL Writing] Were _____ _____ (it) _____ _____ (not/for) _____ _____ (the) _____ _____ (progress) _____ _____ (make/passive) _____ in _____ _____ (the) _____ _____ (previous) _____ _____ (decade), _____ _____ (the) _____ _____ (current) _____ _____ (challenge) _____ _____ (far/greater/be/would) — _____ _____ (an) _____ _____ (acknowledgment) that _____ _____ (should) _____ _____ (not) _____ _____ (justify) _____ _____ (complacency) but _____ _____ (should) _____ _____ (demonstrate) _____ _____ (that) _____ _____ (progress) _____ _____ (possible/is).','Were / it / not / for / the / progress / made / in / the / previous / decade / the / current / challenges / would be far greater / an / acknowledgment / that / should / not / justify / complacency / but / should / demonstrate / that / progress / is possible',NULL,'''Were it not for progress made, would be far greater'' for balanced institutional progress assessment.','hard'),
  (cid,82,282,'gap_fill','[TOEFL Writing] If _____ _____ (the) _____ _____ (lessons) _____ _____ (learn/passive) _____ from _____ _____ (past) _____ _____ (failure) _____ _____ (apply/passive) _____ to _____ _____ (future) _____ _____ (intervention), _____ _____ (the) _____ _____ (probability) of _____ _____ (success) _____ _____ (substantially/higher/would/be) — _____ _____ (but) _____ _____ (institutional) _____ _____ (learning) _____ _____ (reliable/not/is) _____ _____ (to) _____ _____ (occur) _____ _____ (without) _____ _____ (deliberate) _____ _____ (investment) _____ _____ (in) _____ _____ (the) _____ _____ (mechanism) _____ _____ (through/which) it _____ _____ (happen).','If / the / lessons / learned / from / past / failures / were applied / to / future / interventions / the / probability / success / would be substantially higher / but / institutional / learning / is not reliable / to / occur / without / deliberate / investment / in / the / mechanisms / through which / it / happens',NULL,'Type 2 ''If lessons were applied, would be higher'' + conditional for institutional learning argument.','hard'),
  (cid,82,283,'gap_fill','[TOEFL Writing] Had _____ _____ (the) _____ _____ (research) _____ _____ (field) _____ _____ (earlier/invest) _____ in _____ _____ (developing) _____ _____ (standardized) _____ _____ (measure) _____ of _____ _____ (the) _____ _____ (key) _____ _____ (construct), _____ _____ (the) _____ _____ (comparison) _____ _____ (across) _____ _____ (study) _____ _____ (far/more/meaningful/be/would/have) _____ than _____ _____ (they) _____ _____ (currently/are).','Had / the / research / field / earlier invested / in / developing / standardized / measures / the / key / constructs / the / comparisons / across / studies / would have been far more meaningful / than / they / currently are',NULL,'Type 3 ''Had earlier invested, would have been more meaningful'' for research field coordination argument.','hard'),
  (cid,82,284,'gap_fill','[TOEFL Writing] If _____ _____ (this) _____ _____ (argument) _____ _____ (correct/is), then _____ _____ (the) _____ _____ (implication) for _____ _____ (policy) _____ _____ (clear/are) — _____ _____ (if) _____ _____ (it) _____ _____ (not/is), then _____ _____ (the) _____ _____ (data) _____ that _____ _____ (appear) to _____ _____ (support) _____ _____ (it) _____ _____ (require) _____ _____ (a) _____ _____ (different) _____ _____ (explanation), _____ and _____ _____ (that) _____ _____ (explanation) _____ _____ (must) _____ _____ (find/passive).','If / this / argument / is correct / then / the / implications / policy / are clear / if / it / is not / then / the / data / that / appear / to / support / it / require / a / different / explanation / and / that / explanation / must / be found',NULL,'Double Type 1: ''If is correct...if it is not'' for falsificationist academic argument conclusion.','medium'),
  (cid,82,285,'gap_fill','[TOEFL Writing] In _____ _____ (the) _____ _____ (absence) of _____ _____ (better) _____ _____ (evidence), _____ _____ (we) _____ _____ (proceed/must) on _____ _____ (the) _____ _____ (basis) of _____ _____ (what) _____ _____ (we) _____ _____ (have) — _____ _____ (but) _____ _____ (were) _____ _____ (better) _____ _____ (evidence) _____ _____ (available), _____ _____ (it) _____ _____ (obligation/be/would) to _____ _____ (use) _____ _____ (it).','In / the / absence / better / evidence / we / must proceed / on / the / basis / what / we / have / but / were / better / evidence / available / it / would be an obligation / to / use / it',NULL,'''Were better evidence available, would be obligation'' for epistemic obligation in decision-making.','medium'),
  (cid,82,286,'gap_fill','[TOEFL Writing] The _____ _____ (future) _____ _____ (not/fixed/is) — _____ _____ (if) _____ _____ (the) _____ _____ (right) _____ _____ (decision) _____ _____ (make/passive) _____ _____ (now), _____ _____ (the) _____ _____ (trajectory) _____ _____ (change/can) _____ significantly — _____ _____ (but) _____ _____ (if) _____ _____ (the) _____ _____ (same) _____ _____ (pattern) _____ _____ (of) _____ _____ (delay) _____ and _____ _____ (avoidance) _____ _____ (continue), _____ _____ (the) _____ _____ (window) _____ _____ (for) _____ _____ (meaningful) _____ _____ (change) _____ _____ (close/will).','The / future / is not fixed / if / the / right / decisions / are made / now / the / trajectory / can change / significantly / but / if / the / same / pattern / of / delay / avoidance / continues / the / window / for / meaningful / change / will close',NULL,'Double Type 1: ''If are made now/if continues'' for policy urgency conclusion.','medium'),
  (cid,82,287,'gap_fill','[TOEFL Writing] _____ _____ (nothing) _____ _____ (less) _____ _____ (is) _____ _____ (at) _____ _____ (stake) _____ than _____ _____ (the) _____ _____ (quality) of _____ _____ (the) _____ _____ (institution) through _____ _____ (which) _____ _____ (we) _____ _____ (make) _____ _____ (collective) _____ _____ (decision) — _____ _____ (and) _____ _____ (were) _____ _____ (we) _____ _____ (to) _____ _____ (take) _____ _____ (that) _____ _____ (seriously), _____ _____ (we) _____ _____ (invest/would) _____ in _____ _____ (institutional) _____ _____ (quality) _____ as _____ _____ (we) _____ _____ (invest) _____ in _____ _____ (physical) _____ _____ (infrastructure).','Nothing / less / is / at / stake / than / the / quality / the / institutions / through / which / we / make / collective / decisions / and / were / we / to / take / that / seriously / we / would invest / in / institutional / quality / as / we / invest / in / physical / infrastructure',NULL,'''Were we to take seriously, would invest'' for institutional investment argument conclusion.','hard'),
  (cid,82,288,'production','[TOEFL Writing — Final 200 words] Write a conclusion using Type 2 and Type 3 conditionals to synthesize the argument about governance reform.','',NULL,'The argument developed in this essay rests on a conditional logic that is both retrospective and prospective. Retrospectively, had the institutional reforms of the previous era been more thoroughly implemented, the governance problems we observe today would be considerably less severe, and the political capital required to address them would be more readily available. The path dependency that makes institutional change difficult is itself the product of earlier choices — choices that, had they been different, would have produced a different set of constraints and opportunities today. Prospectively, if the analysis presented here is correct, then the policy implications are clear: the reforms that would produce the greatest improvement in governance quality are those that address the incentive structures through which institutional behavior is shaped, rather than those that focus primarily on formal rules whose effect depends entirely on the quality of implementation. Were these reforms implemented with the consistency and political support that sustained institutional change requires, the trajectory of governance performance could be meaningfully improved over a decade-long time horizon. Neither the retrospective nor the prospective argument is a guarantee — had things been different in the past, they might still have gone wrong for other reasons, and if reforms are adopted in the future, they may still face obstacles that prevent them from achieving their potential. But the conditional logic that connects design choices to institutional performance is the most useful tool we have for learning from the past and for making better choices in the future.','hard'),
  (cid,82,289,'gap_fill','[TOEFL Writing] The _____ _____ (past) _____ _____ (cannot) _____ _____ (change/passive) — _____ _____ (but) _____ _____ (the) _____ _____ (future) _____ _____ (can) _____ _____ (be) _____ _____ (different), _____ _____ (if) _____ _____ (we) _____ _____ (willing/are) to _____ _____ (learn) _____ from _____ _____ (it) _____ _____ (and) _____ _____ (to) _____ _____ (act) on _____ _____ (what) _____ _____ (we) _____ _____ (learn).','The / past / cannot / be changed / but / the / future / can / be / different / if / we / are willing / to / learn / from / it / and / to / act / on / what / we / learn',NULL,'Simple Type 1 ''can be different, if willing to learn'' for balanced retrospective-prospective conclusion.','easy'),
  (cid,82,290,'gap_fill','[TOEFL Writing] Had _____ _____ (we) _____ _____ (solve) _____ _____ (these) _____ _____ (problem) _____ _____ (already), _____ _____ (there) _____ _____ (be/would) _____ _____ (no) _____ _____ (need) _____ for _____ _____ (this) _____ _____ (analysis) — _____ _____ (it) _____ _____ (precisely/is) _____ _____ (because) _____ _____ (they) _____ _____ (prove) _____ _____ (resistant) _____ _____ (to) _____ _____ (easy) _____ _____ (solution) that _____ _____ (the) _____ _____ (careful) _____ _____ (analysis) _____ undertaken _____ _____ (here) _____ _____ (necessary/is).','Had / we / solved / these / problems / already / there / would be / no / need / for / this / analysis / it / is precisely / because / they / have proved / resistant / to / easy / solutions / that / the / careful / analysis / undertaken / here / is necessary',NULL,'Type 3 ''Had we solved, would be no need'' for self-justifying academic argument conclusion.','medium'),
  (cid,82,291,'production','[TOEFL Writing — 200 words] Write a final capstone paragraph synthesizing conditionals, relative clauses, and passive voice for a conclusion on policy reform.','',NULL,'The reforms that have been analyzed in this essay were designed with the intention of addressing governance failures that had been identified by prior diagnostic work. Were the most optimistic assessment of their potential to be borne out, the institutions through which collective decisions are made would, within a decade, be operating more effectively than they do today — better aligned with the interests of the populations they are supposed to serve, more transparent in the reasoning by which their decisions are made, and more genuinely accountable to the oversight mechanisms that have been established to check their performance. Had the reforms been designed with greater attention to the political economy of implementation — to the interests that would be threatened by meaningful change and to the mechanisms through which those interests could be expected to resist it — the probability of achieving this outcome would be higher. As it is, the reforms face significant headwinds from exactly the actors whose cooperation they depend on but whose interests they challenge. If these headwinds are not addressed — through the political strategies, resource commitments, and institutional safeguards that effective reform requires — the reforms that have been designed with considerable care will be implemented with considerably less fidelity than their designers intended, and the governance improvements that have been promised to the populations whose lives depend on better institutional performance will be delivered, if at all, only partially and late.','hard'),
  (cid,82,292,'gap_fill','[TOEFL Writing] The _____ _____ (analysis) _____ _____ (is) _____ _____ (complete) — _____ _____ (but) _____ _____ (the) _____ _____ (work) _____ _____ (not/is), _____ _____ (for) _____ _____ (analysis) _____ _____ (purpose/is/whose) _____ to _____ _____ (inform) _____ _____ (action) _____ _____ (has) _____ _____ (not/fulfill) _____ _____ (its) _____ _____ (purpose) _____ _____ (until) _____ _____ (action) _____ _____ (follow).','The / analysis / is / complete / but / the / work / is not / for / analysis / whose purpose is / to / inform / action / has / not fulfilled / its / purpose / until / action / follows',NULL,'''Analysis whose purpose is to inform action has not fulfilled its purpose until action follows'' — final sentence.','medium'),
  (cid,82,293,'gap_fill','[TOEFL Writing] The _____ _____ (question) _____ _____ (was/whether) _____ _____ (the) _____ _____ (reform) _____ _____ (succeed/would) — _____ _____ (the) _____ _____ (answer) _____ _____ (depends) _____ _____ (on) _____ _____ (choices) _____ _____ (not/yet/make/passive).','question / was whether / the / reform / would succeed / the / answer / depends / on / choices / not yet made',NULL,'''The answer depends on choices not yet made'' for open-ended reform conclusion.','easy'),
  (cid,82,294,'production','[TOEFL Writing — Final 200 words] Write a concluding paragraph using mixed, Type 2, and Type 3 conditionals to argue for institutional investment.','',NULL,'The case for investing in institutional quality is ultimately a conditional one: if the institutions through which we govern ourselves were more effective, the outcomes across virtually every domain of public policy would be better. This is not a radical or controversial claim; it is a claim that follows straightforwardly from the evidence about what institutions do and why they matter. The more challenging and contested claim is the practical one: that the investment required to achieve meaningful institutional improvement is feasible, and that the political will to make it can be generated. Had previous reform efforts been sustained with greater consistency — had they been protected from the political cycles that repeatedly interrupted them before their effects could be consolidated — we would currently have substantially stronger evidence about what works, and substantially more institutional capacity on which to build. As it is, we are arguing for a path of investment whose returns are genuine but delayed, in a political environment that systematically discounts the future. Were the political economy of institutional reform to shift — were leaders to find it in their interest to make the investments that their successors would benefit from — the institutional improvements that would follow would be both significant and durable. The analytical work is to demonstrate that this is both possible and worth pursuing; the political work is to create the conditions under which it actually happens.','hard'),
  (cid,82,295,'gap_fill','[TOEFL Writing] _____ _____ (the) _____ _____ (conditions) _____ _____ (for) _____ _____ (success) _____ _____ (present/are), _____ _____ (success) _____ _____ (is/not) _____ _____ (guaranteed) — _____ _____ (but) _____ _____ (without) _____ _____ (them), _____ _____ (it) _____ _____ (near/is) _____ _____ (impossible).','Even when the / conditions / for / success / are present / success / is not / guaranteed / but / without / them / it / is nearly / impossible',NULL,'Conditional caveat ''even when conditions present, not guaranteed / without them, nearly impossible.''','easy'),
  (cid,82,296,'gap_fill','[TOEFL Writing] If _____ _____ (this) _____ _____ (analysis) _____ _____ (change) _____ _____ (nothing) _____ _____ (about) _____ _____ (how) _____ _____ (we) _____ _____ (think) _____ _____ (about) _____ _____ (these) _____ _____ (question), _____ _____ (it) _____ _____ (will/have/fail) _____ in _____ _____ (its) _____ _____ (purpose) — _____ _____ (if) _____ _____ (it) _____ _____ (provoke) _____ _____ (even) _____ _____ (one) _____ _____ (reconsideration), it _____ _____ (will/have/been) _____ _____ (worthwhile).','If / this / analysis / changes / nothing / about / how / we / think / about / these / questions / it / will have failed / in / its / purpose / if / it / provokes / even / one / reconsideration / will have been / worthwhile',NULL,'Future perfect conditional ''will have failed/will have been worthwhile'' for self-evaluating academic conclusion.','medium'),
  (cid,82,297,'gap_fill','[TOEFL Writing] The _____ _____ (argument) _____ _____ (has) _____ _____ (been) _____ _____ (make) _____ — _____ _____ (now) _____ _____ (the) _____ _____ (evidence) _____ _____ (judge/must) _____ _____ (it), _____ _____ (and) _____ _____ (if) _____ _____ (the) _____ _____ (evidence) _____ _____ (judge) _____ _____ (it) _____ _____ (want/passive), _____ _____ (then) _____ _____ (the) _____ _____ (argument) _____ _____ (not/have/served) _____ _____ (its) _____ _____ (purpose).','The / argument / has / been / made / now / the / evidence / must judge / it / and / if / the / evidence / judges / it / wanting / then / the / argument / has not served / its / purpose',NULL,'Type 1 ''if the evidence judges it wanting, has not served its purpose'' for epistemically honest conclusion.','medium'),
  (cid,82,298,'production','[TOEFL Writing — 200 words] Write a final paragraph on what better governance looks like using Type 2 conditionals throughout.','',NULL,'If governance were to function as the most optimistic accounts suggest it could, several things would be true simultaneously that are rarely true together in practice. Decisions would be made by those with the relevant competence and information, rather than by those with the most political power, and those decision-makers would be accountable to clear standards whose application they could not control. Citizens would have access to information about both the decisions being made and the reasoning behind them, so that their assessments of whether those decisions were well-made could be grounded in evidence rather than in ideology or in the framing choices of those with an interest in particular conclusions. Institutions would have the capacity to implement the decisions that are formally made, so that the gap between policy as designed and policy as delivered would be narrow rather than vast. And the incentives facing those in positions of authority would reward serving the public interest over pursuing personal advancement, which would make it more likely that the considerable talents of those who enter public service would be directed at the problems they are supposed to address. Were all of these things true simultaneously, governance would be dramatically better than it is anywhere in the world today. That they are not is not evidence of impossibility; it is evidence of how much work remains to be done.','hard'),
  (cid,82,299,'gap_fill','[TOEFL Writing] _____ _____ (the) _____ _____ (task) _____ _____ (ahead) _____ _____ (large/is) — _____ _____ (but) _____ _____ (were) _____ _____ (it) _____ _____ (not) _____ _____ (large), _____ _____ (it) _____ _____ (would/have) _____ _____ (been) _____ _____ (done) _____ _____ (already), _____ and _____ _____ (this) _____ _____ (argument) _____ _____ (would) _____ _____ (not/need) _____ _____ (making).','The / task / ahead / is large / but / were / it / not / large / it / would have / been / done / already / this / argument / would / not need / making',NULL,'''Were it not large, it would have been done'' for motivational closing argument.','medium'),
  (cid,82,300,'production','[TOEFL Writing — Final capstone 200 words] Write the final conclusion using all conditional types for a synthesis on governance, institutions, and collective action.','',NULL,'This essay has argued that the quality of institutions matters enormously — that if institutions were better designed and better led, the outcomes of collective action would be substantially better across virtually every domain that affects human welfare. It has also argued that the path from where we are to where we could be is both shorter than pessimists suggest and more demanding than optimists acknowledge. Had the institutional investments of the previous generation been more sustained and more strategic, we would currently be in a better position to address the challenges we face. As it is, we inherit institutions that are adequate in some ways and inadequate in others, and the work of improvement must proceed from that inheritance rather than from the blank slate that reformers always wish for but never receive. Were the arguments made here to be taken seriously by those with the authority to act on them, the changes that followed would take a decade or more to consolidate — but they would be changes that the generation inheriting them would be grateful for. If they are not taken seriously — if the cycles of inadequate reform and rising dysfunction continue — then those who inherit the result will ask, reasonably, why the analysis was so clear and the action so absent. It is in the hope of narrowing the gap between analysis and action that arguments like this one are worth making.','hard')

